window.SUBJECT = {"id":"pos361","code":"POS361","title":"Ôn tập Tư tưởng Hồ Chí Minh – POS361","sub":"90 trắc nghiệm &middot; 40 câu hỏi ngắn &middot; 5 dàn ý tự luận &middot; 1 file duy nhất, không cần mạng","accent":"#c2410c","storeKey":"hcm-quiz-v1","tabs":[["quiz","Trắc nghiệm"],["flash","Câu hỏi ngắn"],["essay","Tự luận"],["keys","Ý chính"]],"essayIntro":"Chạm vào từng đề để mở dàn ý chi tiết. Mỗi dàn ý đều có sẵn đoạn <b>liên hệ sinh viên</b> dùng được cho nhiều đề.","roman":null,"QUIZ":[{"c":1,"q":"Thuật ngữ \"Tư tưởng Hồ Chí Minh\" được Đảng ta chính thức sử dụng từ bao giờ?","o":["Từ năm 1930","Từ năm 1945","Từ năm 1990","Từ năm 1991"],"a":3,"t":"Nhớ: <b>1991 – Đại hội VII</b>, cùng năm với Cương lĩnh xây dựng đất nước trong thời kỳ quá độ."},{"c":1,"q":"Thuật ngữ \"Tư tưởng Hồ Chí Minh\" được dùng theo nghĩa nào?","o":["Tư tưởng của một cá nhân","Tư tưởng của một lãnh tụ","Tư tưởng của một giai cấp, một dân tộc","Tất cả các phương án trên"],"a":2,"t":"Không dùng theo nghĩa cá nhân hẹp, mà là tư tưởng của giai cấp, dân tộc."},{"c":1,"q":"Luận điểm: \"Đảng lấy chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động\" được Đảng ta khẳng định lần đầu tiên tại Đại hội nào?","o":["Đại hội IV","Đại hội VI","Đại hội VII","Đại hội VIII"],"a":2,"t":"<b>Đại hội VII (1991)</b> – Cương lĩnh 1991 ghi nhận lần đầu."},{"c":1,"q":"Tư tưởng Hồ Chí Minh là gì?","o":["Hệ thống kiến thức phổ thông","Kết quả của sự vận dụng và phát triển sáng tạo chủ nghĩa Mác – Lênin vào điều kiện cụ thể của nước ta","Hệ thống quan điểm chính trị","Tất cả các phương án trên"],"a":1,"t":"Định nghĩa Đại hội IX: vận dụng và phát triển <b>sáng tạo</b> chủ nghĩa Mác – Lênin vào Việt Nam."},{"c":1,"q":"Câu nói: \"Dân tộc ta, nhân dân ta, non sông đất nước ta đã sinh ra Hồ Chủ tịch...\" được trích từ tác phẩm nào?","o":["Tuyên ngôn Độc lập","Điếu văn của Ban Chấp hành Trung ương Đảng ngày 9/9/1969","Di chúc","Đường cách mệnh"],"a":1,"t":"Điếu văn đọc ngày <b>9/9/1969</b> tại lễ truy điệu Bác."},{"c":1,"q":"Luận điểm: Đảng lấy chủ nghĩa Mác – Lênin làm nền tảng tư tưởng và kim chỉ nam cho hành động được khẳng định lần đầu tiên tại Đại hội nào?","o":["Đại hội I","Đại hội II","Đại hội III","Đại hội IV"],"a":1,"t":"<b>Đại hội II (1951)</b> – Đảng đổi tên thành Đảng Lao động Việt Nam."},{"c":1,"q":"Truyền thống quý báu nhất của dân tộc Việt Nam và của các dân tộc phương Đông là gì?","o":["Truyền thống yêu nước","Giàu tình cảm trong sáng","Truyền thống hiếu học","Truyền thống đoàn kết"],"a":0,"t":"Chính lời Hồ Chí Minh (Đại hội II): \"Dân ta có một lòng nồng nàn <b>yêu nước</b>. Đó là một <b>truyền thống quý báu</b> của ta.\""},{"c":1,"q":"Những giá trị truyền thống nào của dân tộc Việt Nam được Hồ Chí Minh kế thừa?","o":["Truyền thống của các dân tộc phương Đông","Truyền thống của dân tộc Việt Nam","Nhân cách của cá nhân Hồ Chí Minh","Tất cả các phương án trên"],"a":3,"t":"Cả ba: phương Đông + dân tộc Việt Nam + nhân cách cá nhân."},{"c":1,"q":"Ý chí \"tự lực, tự cường\" trong tư tưởng Hồ Chí Minh thể hiện ở điểm nào?","o":["Tinh thần độc lập, tự chủ, sáng tạo","Tinh thần đoàn kết","Tinh thần nhân ái","Tinh thần quốc tế"],"a":0,"t":"Tự lực tự cường = <b>độc lập, tự chủ</b>, không trông chờ ỷ lại."},{"c":1,"q":"Đối tượng nghiên cứu của môn học Tư tưởng Hồ Chí Minh là gì?","o":["Cuộc đời và sự nghiệp của Hồ Chí Minh","Hệ thống quan điểm lý luận của Đảng","Hệ thống quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của cách mạng Việt Nam","Tất cả các phương án trên"],"a":2,"t":"Đối tượng = <b>hệ thống quan điểm</b> (tư tưởng), không phải tiểu sử."},{"c":1,"q":"Nhiệm vụ nghiên cứu môn học Tư tưởng Hồ Chí Minh là gì?","o":["Làm rõ nội dung, bản chất cách mạng và khoa học của tư tưởng Hồ Chí Minh","Làm rõ nguồn gốc, quá trình hình thành và phát triển tư tưởng Hồ Chí Minh","Làm rõ giá trị, ý nghĩa của tư tưởng Hồ Chí Minh","Tất cả các phương án trên"],"a":3,"t":"Nhiệm vụ gồm 3: <b>nội dung – nguồn gốc – giá trị</b>."},{"c":1,"q":"Cơ sở phương pháp luận để nghiên cứu tư tưởng Hồ Chí Minh là gì?","o":["Quan điểm thực tiễn","Quan điểm lịch sử – cụ thể","Quan điểm toàn diện và phát triển","Tất cả các phương án trên"],"a":3,"t":"Ba quan điểm của phép biện chứng duy vật."},{"c":1,"q":"Vai trò của việc học tập môn Tư tưởng Hồ Chí Minh là gì?","o":["Nâng cao năng lực tư duy lý luận và phương pháp công tác","Bồi dưỡng phẩm chất đạo đức cách mạng","Vận dụng vào giải quyết các vấn đề trong thực tiễn","Tất cả các phương án trên"],"a":3,"t":"Học để: <b>tư duy – đạo đức – hành động</b>."},{"c":1,"q":"Hệ thống tri thức lý luận của tư tưởng Hồ Chí Minh bao gồm những gì?","o":["Hệ thống lý luận","Phương pháp nhận thức và hành động","Chuẩn mực đạo đức","Tất cả các phương án trên"],"a":3,"t":"Tri thức = lý luận + phương pháp + chuẩn mực."},{"c":1,"q":"Nghiên cứu tư tưởng Hồ Chí Minh cần sử dụng phương pháp tiếp cận nào?","o":["Phương pháp lịch sử","Phương pháp tiếp cận liên ngành","Phương pháp logic","Phương pháp so sánh"],"a":1,"t":"tư tưởng Hồ Chí Minh là đối tượng phức hợp nên cần <b>liên ngành</b> (sử, triết, chính trị...)."},{"c":2,"q":"Cuối thế kỷ XIX – đầu thế kỷ XX, trong xã hội Việt Nam tồn tại mâu thuẫn nào?","o":["Giữa nông dân với địa chủ phong kiến","Giữa công nhân với tư sản","Giữa toàn thể nhân dân Việt Nam với thực dân Pháp","Tất cả các phương án trên"],"a":3,"t":"Cả 3 cặp đều <b>tồn tại</b>; nhưng <b>cơ bản</b> chỉ có 2: nông dân–địa chủ và dân tộc–thực dân Pháp."},{"c":2,"q":"Cương lĩnh đầu tiên của Đảng Cộng sản Việt Nam là gì?","o":["Cương lĩnh chính trị đầu tiên (2/1930)","Luận cương chính trị (10/1930)","Cương lĩnh xây dựng đất nước (1991)","Chính cương của Đảng Lao động Việt Nam"],"a":0,"t":"<b>2/1930</b>: Chánh cương vắn tắt, Sách lược vắn tắt do Nguyễn Ái Quốc soạn."},{"c":2,"q":"Tổ chức quốc tế nào có những tài liệu mà Hồ Chí Minh tiếp thu nhiều nhất trong quá trình hình thành tư tưởng?","o":["Quốc tế Cộng sản (Quốc tế III)","Quốc tế Xã hội (Quốc tế II)","Liên hợp quốc","Không có tổ chức nào"],"a":0,"t":"<b>Quốc tế III</b> – nơi có Luận cương của Lênin về vấn đề dân tộc và thuộc địa."},{"c":2,"q":"Hồ Chí Minh kế thừa Nho giáo về phương diện nào?","o":["Tư tưởng về đấu tranh giai cấp","Tư tưởng về triết học duy vật","Tư tưởng về tu dưỡng đạo đức cá nhân","Tư tưởng về kinh tế"],"a":2,"t":"Nho giáo → <b>tu thân</b>, nhân nghĩa, đạo đức người quân tử."},{"c":2,"q":"Hồ Chí Minh kế thừa Lão giáo về phương diện nào?","o":["Tư tưởng đấu tranh vũ trang","Tư tưởng thoát mọi ràng buộc của vòng danh lợi","Tư tưởng về xây dựng nhà nước","Tư tưởng về kinh tế thị trường"],"a":1,"t":"Lão giáo → <b>thoát vòng danh lợi</b>, sống giản dị, gần dân."},{"c":2,"q":"Hồ Chí Minh kế thừa Phật giáo về phương diện nào?","o":["Tinh thần từ bi, bác ái","Tư tưởng vô thần","Tư tưởng xuất thế","Tư tưởng tu hành"],"a":0,"t":"Phật giáo → <b>từ bi, bác ái</b>, thương người như thể thương thân."},{"c":2,"q":"Hồ Chí Minh tiếp thu giá trị văn hoá dân gian ở khía cạnh nào?","o":["Nghệ thuật quân sự","Nghệ thuật kiến trúc","Nghệ thuật ẩm thực","Nghệ thuật ứng xử trong cuộc sống cộng đồng"],"a":3,"t":"Văn hoá dân gian → <b>nghệ thuật ứng xử</b>, ăn ở có tình có nghĩa."},{"c":2,"q":"Sự kiện nào đánh dấu Nguyễn Ái Quốc từ chủ nghĩa yêu nước đến với chủ nghĩa Mác – Lênin?","o":["Tham gia Đảng Xã hội Pháp (1919)","Đại hội Tours của Đảng Xã hội Pháp (12/1920)","Thành lập Hội Liên hiệp thuộc địa (1921)","Dự Đại hội V Quốc tế Cộng sản (1924)"],"a":1,"t":"<b>Đại hội Tours 12/1920</b>: bỏ phiếu tán thành Quốc tế III, thành người cộng sản."},{"c":2,"q":"Nguyễn Ái Quốc tiếp xúc với Luận cương của Lênin về vấn đề dân tộc và thuộc địa vào thời gian nào?","o":["Tháng 7/1920","Tháng 12/1920","Tháng 6/1923","Tháng 2/1930"],"a":0,"t":"<b>7/1920</b> – đọc trên báo L'Humanité, tìm ra con đường cứu nước."},{"c":2,"q":"Thời gian Hồ Chí Minh học tập và hoạt động tại Liên Xô là khi nào?","o":["1923 – 1924","1925 – 1927","1930 – 1931","1941 – 1945"],"a":0,"t":"<b>1923–1924</b>: học Trường Đại học Phương Đông, dự Đại hội V Quốc tế Cộng sản."},{"c":2,"q":"Tác phẩm nào của Lênin có tác động trực tiếp nhất đến việc hình thành con đường cứu nước của Nguyễn Ái Quốc?","o":["Nhà nước và cách mạng","Luận cương của Lênin về các vấn đề dân tộc và thuộc địa","Tuyên ngôn của Đảng Cộng sản","Chủ nghĩa đế quốc – giai đoạn tột cùng của chủ nghĩa tư bản"],"a":1,"t":"<b>Luận cương về vấn đề dân tộc và thuộc địa</b> – kim chỉ nam cho các dân tộc thuộc địa."},{"c":2,"q":"Con đường hình thành tư tưởng Hồ Chí Minh là con đường như thế nào?","o":["Từ giai cấp đến dân tộc","Từ dân tộc đến giai cấp, từ dân tộc đến quốc tế","Từ quốc tế đến dân tộc","Từ giai cấp đến quốc tế"],"a":1,"t":"Đi từ <b>chủ nghĩa yêu nước</b> đến chủ nghĩa Mác – Lênin: dân tộc → giai cấp → quốc tế."},{"c":2,"q":"Hồ Chí Minh về nước trực tiếp lãnh đạo cách mạng Việt Nam vào năm nào?","o":["1941","1930","1945","1954"],"a":0,"t":"<b>1941</b>: về Pác Bó, chủ trì Hội nghị Trung ương 8, lập Mặt trận Việt Minh."},{"c":2,"q":"Sự kiện nào là cột mốc đánh dấu tư tưởng Hồ Chí Minh về con đường cách mạng Việt Nam được hình thành về cơ bản?","o":["Lãnh đạo Cách mạng Tháng Tám (1945)","Thành lập Mặt trận Việt Minh (1941)","Thành lập Đảng Cộng sản Việt Nam (2/1930)","Thành lập Nhà nước Việt Nam Dân chủ Cộng hòa (1945)"],"a":2,"t":"<b>2/1930</b>: Đảng ra đời với Cương lĩnh đúng đắn = tư tưởng Hồ Chí Minh định hình cơ bản."},{"c":2,"q":"Những yếu tố nào tạo nên cơ sở hình thành tư tưởng Hồ Chí Minh?","o":["Giá trị truyền thống tốt đẹp của dân tộc","Tinh hoa văn hoá nhân loại","Chủ nghĩa Mác – Lênin","Tất cả các phương án trên"],"a":3,"t":"3 nguồn: <b>dân tộc + nhân loại + chủ nghĩa Mác – Lênin</b> (chủ nghĩa Mác – Lênin quyết định bước nhảy về chất)."},{"c":3,"q":"Theo Hồ Chí Minh, độc lập dân tộc là gì?","o":["Cơ sở của cách mạng","Nội dung cốt lõi của tư tưởng","Điều kiện tiên quyết để đi tới chủ nghĩa xã hội","Mục tiêu cuối cùng"],"a":2,"t":"độc lập dân tộc là <b>điều kiện tiên quyết</b>; còn \"nội dung cốt lõi\" là <b>độc lập dân tộc gắn liền với chủ nghĩa xã hội</b>."},{"c":3,"q":"Cách mạng giải phóng dân tộc theo tư tưởng Hồ Chí Minh là gì?","o":["Nội dung chủ yếu của cách mạng Việt Nam","Nhiệm vụ phụ của cách mạng","Đối tượng của cách mạng","Mục tiêu xa của cách mạng"],"a":0,"t":"cách mạng giải phóng dân tộc là <b>nội dung chủ yếu, nhiệm vụ hàng đầu</b> của cách mạng Việt Nam."},{"c":3,"q":"Cách mạng giải phóng dân tộc muốn thắng lợi phải đi theo con đường nào?","o":["Con đường cải lương tư sản","Con đường cách mạng vô sản","Con đường dân chủ tư sản","Con đường trung lập"],"a":1,"t":"\"Muốn cứu nước, giải phóng dân tộc <b>không có con đường nào khác</b> con đường CMVS\"."},{"c":3,"q":"Cách mạng giải phóng dân tộc trong thời đại mới phải do ai lãnh đạo?","o":["Đảng của giai cấp công nhân","Giai cấp tư sản dân tộc","Tầng lớp trí thức","Giai cấp địa chủ"],"a":0,"t":"Phải do <b>Đảng của giai cấp công nhân</b> lãnh đạo mới thắng lợi triệt để."},{"c":3,"q":"Lực lượng của cách mạng giải phóng dân tộc bao gồm những ai?","o":["Giai cấp công nhân","Giai cấp nông dân","Toàn dân tộc","Liên minh công – nông"],"a":2,"t":"Lực lượng là <b>toàn dân tộc</b>, nòng cốt liên minh công–nông–trí thức."},{"c":3,"q":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc ở thuộc địa có quan hệ thế nào với cách mạng vô sản ở chính quốc?","o":["Phụ thuộc hoàn toàn vào chính quốc","Có thể nổ ra và thắng lợi trước cách mạng vô sản ở chính quốc","Không liên quan gì đến chính quốc","Chỉ nổ ra sau khi chính quốc thắng lợi"],"a":1,"t":"Sáng tạo của Hồ Chí Minh: thuộc địa <b>chủ động, có thể thắng trước</b>, không bị động chờ."},{"c":3,"q":"Theo Hồ Chí Minh, chủ nghĩa xã hội là gì?","o":["Giai đoạn đầu của hình thái kinh tế – xã hội cộng sản chủ nghĩa","Giai đoạn cao của chủ nghĩa cộng sản","Một chế độ xã hội tốt đẹp trừu tượng","Một hình thái kinh tế tư bản"],"a":0,"t":"chủ nghĩa xã hội = <b>giai đoạn đầu (giai đoạn thấp)</b> của hình thái kinh tế – xã hội cộng sản chủ nghĩa."},{"c":3,"q":"Theo Hồ Chí Minh, đặc trưng kinh tế nổi bật nhất của chủ nghĩa xã hội là gì?","o":["Sở hữu xã hội về tư liệu sản xuất","Cơ cấu kinh tế công – nông nghiệp hợp lý","Sở hữu tư nhân về của cải","Khoa học – kỹ thuật phát triển cao"],"a":0,"t":"Kinh tế: <b>chế độ công hữu (sở hữu xã hội) về tư liệu sản xuất</b> chủ yếu."},{"c":3,"q":"Theo Hồ Chí Minh, đặc trưng văn hoá nổi bật nhất của chủ nghĩa xã hội là gì?","o":["Có nền văn hoá đậm đà bản sắc dân tộc; con người được phát triển toàn diện","Mọi người có cuộc sống ấm no, tự do, hạnh phúc","Các dân tộc bình đẳng, đoàn kết, giúp đỡ nhau","Có quan hệ hữu nghị, hợp tác với nhân dân các nước"],"a":0,"t":"Văn hoá: <b>tiên tiến, đậm đà bản sắc dân tộc</b>; con người phát triển toàn diện."},{"c":3,"q":"Theo Hồ Chí Minh, xây dựng chủ nghĩa xã hội là một công việc như thế nào?","o":["Dễ dàng, nhanh chóng","Cuộc đấu tranh cách mạng phức tạp, gian khổ, lâu dài","Chỉ cần có quyết tâm là xong","Chỉ là nhiệm vụ của Nhà nước"],"a":1,"t":"\"Xây dựng chủ nghĩa xã hội là cuộc đấu tranh cách mạng <b>phức tạp, gian khổ, lâu dài</b>\"."},{"c":3,"q":"Theo Hồ Chí Minh, đặc trưng nổi bật nhất về chính trị của chủ nghĩa xã hội là gì?","o":["Đảng Cộng sản lãnh đạo","Thực hiện một nền dân chủ triệt để","Mọi người được hưởng quyền con người","Thực hiện quyền dân tộc tự quyết"],"a":1,"t":"Chính trị: <b>chế độ dân chủ triệt để</b>, quyền lực thuộc về nhân dân."},{"c":3,"q":"Theo Hồ Chí Minh, động lực quan trọng và quyết định nhất của chủ nghĩa xã hội là gì?","o":["Con người","Khoa học – kỹ thuật","Nguồn vốn","Tài nguyên thiên nhiên"],"a":0,"t":"\"Muốn xây dựng chủ nghĩa xã hội, trước hết cần có những <b>con người xã hội chủ nghĩa</b>\"."},{"c":3,"q":"Động lực của chủ nghĩa xã hội theo tư tưởng Hồ Chí Minh bao gồm những gì?","o":["Đại đoàn kết toàn dân tộc","Phát huy quyền làm chủ và ý thức tập thể của nhân dân","Phong trào thi đua yêu nước","Tất cả các phương án trên"],"a":3,"t":"3 động lực: <b>đoàn kết – làm chủ – thi đua</b>."},{"c":3,"q":"Theo Hồ Chí Minh, biện chứng của sự phát triển kinh tế là gì?","o":["Phát triển kinh tế gắn liền với phát triển văn hoá, xã hội; phát triển công nghiệp và nông nghiệp","Phát triển công nghiệp đi đôi với phát triển thủ công nghiệp","Kết hợp tốt ba lợi ích: lợi ích chung, lợi ích tập thể, lợi ích cá nhân","Tất cả đều đúng"],"a":0,"t":"Nhớ hình ảnh <b>\"hai chân\"</b>: công nghiệp và nông nghiệp giúp nhau cùng phát triển."},{"c":3,"q":"Động lực to lớn của chủ nghĩa xã hội theo Hồ Chí Minh là gì?","o":["Tinh thần yêu nước","Lao động sáng tạo của nhân dân","Ý thức tập thể của người lao động","Tất cả các phương án trên"],"a":3,"t":"Động lực tinh thần: <b>yêu nước – sáng tạo – tập thể</b>."},{"c":4,"q":"Bản chất của Đảng Cộng sản Việt Nam theo tư tưởng Hồ Chí Minh là gì?","o":["Đảng của giai cấp tư sản","Đảng của giai cấp công nhân","Đảng của giai cấp nông dân","Đảng của tầng lớp trí thức"],"a":1,"t":"Đảng mang <b>bản chất giai cấp công nhân</b>, đồng thời là Đảng của nhân dân lao động và của cả dân tộc."},{"c":4,"q":"Theo Hồ Chí Minh, Đảng muốn vững mạnh phải được xây dựng trên những mặt nào?","o":["Về chính trị","Về tư tưởng và tổ chức","Về đạo đức","Về kinh tế"],"a":1,"t":"\"Đảng muốn vững thì phải có <b>chủ nghĩa làm cốt</b>\" + nguyên tắc tổ chức chặt chẽ. Đầy đủ là 4 mặt: chính trị – tư tưởng – tổ chức – đạo đức; trong 4 đáp án của đề thì B đúng nhất."},{"c":4,"q":"Đảng Cộng sản Việt Nam do Hồ Chí Minh sáng lập và lãnh đạo, hoạt động vì lợi ích của ai?","o":["Vì lợi ích của dân tộc Việt Nam","Vì lợi ích của bản thân Đảng","Vì lợi ích của giai cấp công nhân","Vì lợi ích của công nhân, nông dân, trí thức"],"a":0,"t":"Theo đáp án ngân hàng đề: <b>vì lợi ích của dân tộc Việt Nam</b>. Câu này dễ nhầm C/D, học thuộc lòng."},{"c":4,"q":"Đảng lãnh đạo là nhân tố có ý nghĩa thế nào đối với thắng lợi của cách mạng nước ta?","o":["Có ý nghĩa quan trọng","Có ý nghĩa rất quan trọng","Có ý nghĩa quan trọng đặc biệt","Có ý nghĩa quyết định hàng đầu"],"a":3,"t":"Mức cao nhất: <b>quyết định hàng đầu</b> thắng lợi của cách mạng Việt Nam."},{"c":4,"q":"Hồ Chí Minh diễn đạt như thế nào về vấn đề \"Đảng của ai\"?","o":["Đảng Lao động Việt Nam là Đảng của giai cấp công nhân và nhân dân lao động, nên nó phải là Đảng của dân tộc Việt Nam","Đảng Lao động là tổ chức cao nhất của giai cấp công nhân và nhân dân lao động, nên nó phải là Đảng của giai cấp cần lao và đại biểu trung thành lợi ích của cả dân tộc","Đảng là Đảng của giai cấp lao động, mà cũng là Đảng của toàn dân","Các phương án trên đều đúng"],"a":1,"t":"Học thuộc nguyên văn đáp án đúng: \"<b>tổ chức cao nhất</b>... <b>đại biểu trung thành</b> lợi ích của cả dân tộc\"."},{"c":4,"q":"Trong tư tưởng Hồ Chí Minh, là người lãnh đạo, Đảng phải có những phẩm chất gì?","o":["Tư cách, đạo đức, năng lực cần thiết","Có khả năng làm cho dân tin, dân mến, dân phục, dân theo","Gắn bó mật thiết với nhân dân, chịu sự kiểm soát của nhân dân","Tất cả những phẩm chất trên"],"a":3,"t":"Cả ba: <b>đức – tài – gắn bó với dân</b>."},{"c":4,"q":"Chọn đáp án SAI trong những nội dung rút ra từ mệnh đề: \"Đảng ta vừa là người lãnh đạo, vừa là người đầy tớ thật trung thành của nhân dân\"?","o":["Đầy tớ là tôi tớ, tôi đòi, theo đuôi quần chúng","Là tận tâm, tận lực phụng sự quần chúng","Việc gì có lợi cho dân thì phải hết sức làm, việc gì có hại cho dân thì phải hết sức tránh","Là khổ trước thiên hạ, vui sau thiên hạ"],"a":0,"t":"Đầy tớ trung thành = <b>phụng sự</b> dân, không phải <b>theo đuôi</b> dân."},{"c":4,"q":"Nguyên tắc đoàn kết trong Đảng theo tư tưởng Hồ Chí Minh là gì?","o":["Đoàn kết trong Đảng là hạt nhân","Đoàn kết toàn dân là nền tảng","Đoàn kết quốc tế là bạn đồng minh","Tất cả các phương án trên"],"a":3,"t":"3 tầng đoàn kết: <b>hạt nhân – nền tảng – đồng minh</b>."},{"c":4,"q":"Tư cách của người cách mệnh theo Hồ Chí Minh bao gồm những gì?","o":["Tự mình phải cần, kiệm","Hăng hái, quyết đoán","Gắn bó với nhân dân","Tất cả các phương án trên"],"a":3,"t":"Xem \"Tư cách một người cách mệnh\" trong <i>Đường Kách mệnh</i>."},{"c":4,"q":"Hồ Chí Minh khẳng định: \"... là cái gốc của mọi công việc\"?","o":["Đường lối đúng","Cán bộ","Quần chúng nhân dân","Tiền bạc"],"a":1,"t":"\"<b>Cán bộ là cái gốc</b> của mọi công việc\"; \"muôn việc thành công hoặc thất bại đều do cán bộ tốt hoặc kém\"."},{"c":4,"q":"Theo Hồ Chí Minh, phẩm chất đạo đức cơ bản của người cán bộ cách mạng là gì?","o":["Trung với Đảng, với nước, với dân","Tuyệt đối trung thành với Đảng","Trung thành với lợi ích của giai cấp công nhân, nhân dân lao động và dân tộc","Tất cả các phương án trên"],"a":3,"t":"Cả ba đều đúng nên chọn <b>tất cả</b>."},{"c":4,"q":"Theo Hồ Chí Minh, chuẩn mực để đánh giá bản chất cách mạng của Đảng Cộng sản là gì?","o":["Đảng có thu hút được đông đảo quần chúng không","Mọi hoạt động của Đảng đều xuất phát từ yêu cầu phát triển của dân tộc, lấy lợi ích tối cao của dân tộc làm trọng","Đảng có tập hợp được đông đảo quần chúng vào tổ chức không","Tất cả đều sai"],"a":1,"t":"Chuẩn mực \"Đảng văn minh\": <b>lợi ích tối cao của dân tộc</b> đặt trên hết."},{"c":4,"q":"Trong điều kiện Đảng cầm quyền, Hồ Chí Minh yêu cầu Đảng phải làm gì?","o":["Mở rộng quy mô tổ chức","Tự đổi mới, tự chỉnh đốn","Tăng cường quyền lực","Giảm bớt đảng viên"],"a":1,"t":"Đảng cầm quyền phải <b>thường xuyên tự đổi mới, tự chỉnh đốn</b>."},{"c":4,"q":"Để xây dựng Nhà nước có hiệu lực pháp lý mạnh mẽ, Hồ Chí Minh chủ trương gì?","o":["Chỉ cần pháp luật nghiêm minh","Chỉ cần giáo dục đạo đức","Tăng cường tính nghiêm minh của pháp luật đi đôi với đẩy mạnh giáo dục đạo đức","Giảm nhẹ pháp luật"],"a":2,"t":"Kết hợp <b>pháp trị + đức trị</b>: nghiêm minh pháp luật đi đôi với giáo dục đạo đức."},{"c":4,"q":"Theo Hồ Chí Minh, Nhà nước ta là Nhà nước như thế nào?","o":["Nhà nước của giai cấp công nhân","Nhà nước của dân, do dân, vì dân","Nhà nước của Đảng","Nhà nước của chính phủ"],"a":1,"t":"Bản chất: <b>của dân, do dân, vì dân</b>; mọi quyền lực thuộc về nhân dân."},{"c":5,"q":"Theo Hồ Chí Minh, đại đoàn kết dân tộc có vai trò như thế nào?","o":["Là vấn đề sách lược","Là vấn đề có ý nghĩa chiến lược, quyết định thành công của cách mạng","Là vấn đề tạm thời","Là vấn đề thứ yếu"],"a":1,"t":"\"<b>Đoàn kết, đoàn kết, đại đoàn kết. Thành công, thành công, đại thành công.</b>\""},{"c":5,"q":"Hình thức tổ chức của khối đại đoàn kết dân tộc theo tư tưởng Hồ Chí Minh là gì?","o":["Mặt trận dân tộc thống nhất","Đảng Cộng sản","Nhà nước","Đoàn thanh niên"],"a":0,"t":"Đại đoàn kết phải thành <b>lực lượng vật chất có tổ chức</b> = Mặt trận dân tộc thống nhất."},{"c":5,"q":"Nền tảng của khối đại đoàn kết dân tộc là gì?","o":["Liên minh công nhân, nông dân và trí thức","Liên minh công nhân và tư sản","Liên minh nông dân và địa chủ","Liên minh trí thức và tư sản"],"a":0,"t":"Nền tảng: <b>liên minh công – nông – trí thức</b> dưới sự lãnh đạo của Đảng."},{"c":5,"q":"Theo Hồ Chí Minh, đại đoàn kết dân tộc là gì?","o":["Mục tiêu của cách mạng","Mục tiêu, nhiệm vụ hàng đầu của cách mạng","Phương tiện của cách mạng","Kết quả của cách mạng"],"a":1,"t":"Phân biệt: câu 1 hỏi <b>vai trò</b> (chiến lược), câu này hỏi <b>tính chất</b> (mục tiêu, nhiệm vụ hàng đầu)."},{"c":5,"q":"Theo Hồ Chí Minh, để củng cố khối đại đoàn kết cần phải làm gì?","o":["Chỉ đoàn kết, không đấu tranh","Kết hợp chặt chẽ đoàn kết và đấu tranh","Chỉ đấu tranh, không đoàn kết","Đoàn kết một chiều"],"a":1,"t":"<b>Đoàn kết gắn với đấu tranh</b>: đấu tranh để củng cố và mở rộng đoàn kết."},{"c":5,"q":"Đối với phong trào cộng sản và công nhân quốc tế, Hồ Chí Minh giương cao ngọn cờ gì?","o":["Độc lập, tự do và quyền bình đẳng giữa các dân tộc","Độc lập dân tộc gắn liền với chủ nghĩa xã hội","Hoà bình trong công lý","Cả ba ngọn cờ trên"],"a":1,"t":"Nhớ bộ 3: <b>Cộng sản–công nhân → độc lập dân tộc gắn chủ nghĩa xã hội</b>; các dân tộc → độc lập, tự do, bình đẳng; lực lượng tiến bộ → hoà bình trong công lý."},{"c":5,"q":"Đối với các dân tộc trên thế giới, Hồ Chí Minh giương cao ngọn cờ gì?","o":["Độc lập dân tộc gắn liền với chủ nghĩa xã hội","Độc lập, tự do và quyền bình đẳng giữa các dân tộc","Hoà bình trong công lý","Cả ba ngọn cờ trên"],"a":1,"t":"Với <b>các dân tộc</b> → ngọn cờ <b>độc lập, tự do và quyền bình đẳng</b>."},{"c":5,"q":"Trong những khẩu hiệu tập hợp lực lượng dưới đây, khẩu hiệu nào do Hồ Chí Minh nêu lên?","o":["Nhân dân yêu chuộng hoà bình và công lý trên thế giới đoàn kết lại","Vô sản tất cả các nước liên hiệp lại","Vô sản các nước và các dân tộc bị áp bức trên thế giới đoàn kết lại","Lao động tất cả các nước đoàn kết lại"],"a":3,"t":"Mác: \"Vô sản tất cả các nước đoàn kết lại\"; Lênin thêm \"<b>và các dân tộc bị áp bức</b>\"; Hồ Chí Minh phát triển thành \"<b>Lao động tất cả các nước đoàn kết lại</b>\" (1923)."},{"c":5,"q":"Để tranh thủ sự đồng tình, ủng hộ của quốc tế, Hồ Chí Minh chủ trương gì?","o":["Tự lực cánh sinh, dựa vào sức mình là chính","Giữ vững độc lập, tự chủ","Tranh thủ sự giúp đỡ quốc tế","Tất cả các phương án trên"],"a":3,"t":"\"<b>Một dân tộc không tự lực cánh sinh mà cứ ngồi chờ dân tộc khác giúp đỡ thì không xứng đáng được độc lập.</b>\""},{"c":5,"q":"Câu nói: \"Hỡi đồng bào yêu quý! Giờ quyết định vận mệnh của dân tộc đã đến...\" được trích từ văn kiện nào?","o":["Quân lệnh số một của Uỷ ban khởi nghĩa toàn quốc","Lời kêu gọi toàn quốc kháng chiến của Hồ Chủ tịch","Hiệu triệu tổng khởi nghĩa","Tuyên ngôn Độc lập"],"a":2,"t":"<b>8/1945 – Hiệu triệu tổng khởi nghĩa</b>. Đừng nhầm với Lời kêu gọi toàn quốc kháng chiến (19/12/1946)."},{"c":5,"q":"\"Hỡi đồng bào yêu quý! Giờ quyết định vận mệnh của dân tộc đã đến. Toàn quốc đồng bào hãy đứng dậy, đem sức ta mà giải phóng cho ta\" – Lời kêu gọi trên được trích từ văn kiện nào?","o":["Quân lệnh số một của Uỷ ban khởi nghĩa toàn quốc","Lời kêu gọi toàn quốc kháng chiến của Hồ Chủ tịch","Hiệu triệu tổng khởi nghĩa","Tuyên ngôn Độc lập"],"a":2,"t":"Cùng một văn kiện với câu trên: <b>Hiệu triệu tổng khởi nghĩa, tháng 8/1945</b>."},{"c":5,"q":"Theo Hồ Chí Minh, nhân tố quyết định nhất, đảm bảo sự thành công của sự nghiệp xây dựng chủ nghĩa xã hội là gì?","o":["Lực lượng vật chất","Chính sách đúng","Đường lối chính trị đúng","Lực lượng vật chất và tinh thần"],"a":0,"t":"<b>Lưu ý:</b> theo giáo trình, nhân tố quyết định nhất là \"<b>con người</b>\" (nhân dân lao động) — nhưng không có trong 4 lựa chọn; đáp án A là theo ngân hàng đề. Nên hỏi lại giảng viên đáp án chính thức."},{"c":5,"q":"Nguyên tắc xây dựng khối đại đoàn kết dân tộc theo tư tưởng Hồ Chí Minh là gì?","o":["Đoàn kết trên cơ sở lợi ích nhóm","Đảm bảo vai trò lãnh đạo của Đảng","Đoàn kết không cần lãnh đạo","Đoàn kết tự phát"],"a":1,"t":"Mặt trận đặt dưới <b>sự lãnh đạo của Đảng</b>; Đảng lãnh đạo bằng uy tín và chính sách đúng."},{"c":5,"q":"Theo Hồ Chí Minh, để mở rộng quan hệ hữu nghị, hợp tác quốc tế cần phải làm gì?","o":["Chỉ quan hệ với các nước xã hội chủ nghĩa","Quan hệ với tất cả các nước trên nguyên tắc tôn trọng độc lập, chủ quyền, bình đẳng, cùng có lợi","Kết hợp sức mạnh dân tộc với sức mạnh thời đại","Tất cả các phương án trên"],"a":3,"t":"Đối ngoại Hồ Chí Minh: <b>rộng mở + có nguyên tắc + kết hợp sức mạnh dân tộc và thời đại</b>."},{"c":5,"q":"Câu nói: \"Nước Việt Nam là một, dân tộc Việt Nam là một...\" được Hồ Chí Minh nói vào năm nào?","o":["1957","1954","1960","1969"],"a":0,"t":"<b>1957</b> – khẳng định quyết tâm thống nhất đất nước."},{"c":6,"q":"Theo Hồ Chí Minh, vai trò của đạo đức đối với người cách mạng là gì?","o":["Đạo đức là phụ","Đạo đức là thứ yếu","Đạo đức là gốc của người cách mạng","Đạo đức không quan trọng"],"a":2,"t":"\"Cũng như sông thì có <b>nguồn</b> mới có nước, không có nguồn thì sông cạn.\""},{"c":6,"q":"Tác phẩm nào của Hồ Chí Minh đề cập nhiều nhất đến vấn đề đạo đức?","o":["Tuyên ngôn Độc lập","Di chúc","Đường cách mệnh","Nhật ký trong tù"],"a":2,"t":"<i>Đường Kách mệnh</i> (1927) có hẳn mục \"<b>Tư cách một người cách mệnh</b>\"."},{"c":6,"q":"Truyền thống quý báu nhất của các dân tộc phương Đông theo Hồ Chí Minh là gì?","o":["Truyền thống yêu nước","Giàu tình cảm trong sáng","Truyền thống hiếu học","Truyền thống cần cù"],"a":1,"t":"Phương Đông: <b>giàu tình cảm trong sáng</b> – nền của lòng nhân ái Hồ Chí Minh."},{"c":6,"q":"Bốn đức \"cần, kiệm, liêm, chính\" được Hồ Chí Minh giải thích như thế nào?","o":["Cần, kiệm, liêm, chính là bốn đức của người cách mạng","Cần, kiệm, liêm là gốc rễ của chính","Cả hai phương án trên đều đúng","Cả hai phương án trên đều sai"],"a":2,"t":"Nhớ: \"<b>Cần, kiệm, liêm là gốc rễ của chính</b>\"."},{"c":6,"q":"Theo Hồ Chí Minh, chủ nghĩa cá nhân là gì?","o":["Động lực của cách mạng","Kẻ thù hung ác của đạo đức cách mạng","Biểu hiện của tự do cá nhân","Phẩm chất tốt đẹp"],"a":1,"t":"chủ nghĩa cá nhân là \"<b>kẻ thù hung ác</b>\", đẻ ra tham ô, lãng phí, quan liêu..."},{"c":6,"q":"Nội dung cơ bản của tư tưởng đạo đức Hồ Chí Minh bao gồm những gì?","o":["Nâng cao đạo đức cách mạng","Kiên quyết chống chủ nghĩa cá nhân","Thực hiện tự phê bình và phê bình","Tất cả các phương án trên"],"a":3,"t":"3 nội dung: <b>nâng cao – chống chủ nghĩa cá nhân – tự phê bình và phê bình</b>."},{"c":6,"q":"Phẩm chất đạo đức nổi bật nhất của Hồ Chí Minh là gì?","o":["Cần, kiệm, liêm, chính","Trung với nước, hiếu với dân","Thương yêu con người, sống có tình có nghĩa","Tinh thần quốc tế trong sáng"],"a":1,"t":"Giáo trình: \"<b>Trung với nước, hiếu với dân</b>\" là phẩm chất đạo đức <b>quan trọng nhất, bao trùm nhất</b>, chi phối các phẩm chất khác."},{"c":6,"q":"Theo Hồ Chí Minh, phẩm chất đạo đức cách mạng trung tâm, chủ yếu nhất là gì?","o":["Trung với nước, hiếu với dân","Cần, kiệm, liêm, chính","Nhân, nghĩa, trí, dũng","Chí công vô tư"],"a":0,"t":"\"Điều <b>chủ chốt nhất</b> của đạo đức cách mạng là... <b>trung với nước, hiếu với dân</b>\"."},{"c":6,"q":"Nguyên tắc tu dưỡng, rèn luyện đạo đức theo tư tưởng Hồ Chí Minh là gì?","o":["Nói đi đôi với làm","Xây đi đôi với chống","Tu dưỡng đạo đức suốt đời","Tất cả các phương án trên"],"a":3,"t":"3 nguyên tắc: <b>nói–làm; xây–chống; suốt đời</b>."},{"c":6,"q":"Tác phẩm \"Đạo đức cách mạng\" được Hồ Chí Minh viết vào năm nào?","o":["1958","1960","1965","1969"],"a":0,"t":"Bài <i>Đạo đức cách mạng</i> đăng Tạp chí Học tập, <b>12/1958</b>."},{"c":6,"q":"Vai trò của văn hoá theo tư tưởng Hồ Chí Minh là gì?","o":["Văn hoá là mục tiêu của cách mạng","Văn hoá là động lực của cách mạng","Văn hoá vừa là mục tiêu, vừa là động lực","Văn hoá không liên quan đến cách mạng"],"a":2,"t":"Văn hoá <b>vừa là mục tiêu, vừa là động lực</b> của sự phát triển."},{"c":6,"q":"Theo Hồ Chí Minh, \"đặc quyền, đặc lợi\" là gì?","o":["Quyền lợi chính đáng","Căn bệnh của người cách mạng","Biểu hiện của dân chủ","Phẩm chất tốt"],"a":1,"t":"\"<b>Đặc quyền, đặc lợi</b>\" là căn bệnh đẻ ra từ chủ nghĩa cá nhân."},{"c":6,"q":"Câu \"Giàu sang không thể quyến rũ, nghèo khó không thể chuyển lay, uy vũ không thể khuất phục\" được Hồ Chí Minh viết trong tác phẩm nào?","o":["Đạo đức cách mạng","Di chúc","Sửa đổi lối làm việc","Đường cách mệnh"],"a":3,"t":"Trong <i>Đường Kách mệnh</i> (1927), mục \"<b>Tư cách một người cách mệnh</b>\"."},{"c":6,"q":"Chuẩn mực đạo đức của con người mới xã hội chủ nghĩa theo Hồ Chí Minh bao gồm những gì?","o":["Có tư tưởng xã hội chủ nghĩa","Có đạo đức xã hội chủ nghĩa","Có tác phong xã hội chủ nghĩa","Tất cả các phương án trên"],"a":3,"t":"Con người mới xã hội chủ nghĩa: <b>tư tưởng – đạo đức – tác phong</b> xã hội chủ nghĩa."},{"c":6,"q":"Để chống chủ nghĩa cá nhân, Hồ Chí Minh chủ trương gì?","o":["Nêu cao đạo đức cách mạng","Tăng cường kỷ luật","Giáo dục tư tưởng","Xử phạt nghiêm khắc"],"a":0,"t":"Muốn quét sạch chủ nghĩa cá nhân phải <b>nêu cao đạo đức cách mạng</b> (bài viết 1969)."}],"FLASH":[{"c":1,"q":"Đối tượng nghiên cứu của môn học Tư tưởng Hồ Chí Minh là gì?","a":"Hệ thống quan điểm toàn diện và sâu sắc của Hồ Chí Minh về những vấn đề cơ bản của cách mạng Việt Nam."},{"c":1,"q":"Tư tưởng Hồ Chí Minh được hiểu như thế nào?","a":"Là kết quả của sự vận dụng và phát triển sáng tạo chủ nghĩa Mác – Lênin vào điều kiện cụ thể của Việt Nam; kế thừa giá trị truyền thống dân tộc, tiếp thu tinh hoa văn hoá nhân loại."},{"c":1,"q":"Phương pháp luận nghiên cứu tư tưởng Hồ Chí Minh dựa trên cơ sở nào?","a":"Cơ sở phương pháp luận của chủ nghĩa Mác – Lênin: quan điểm thực tiễn, quan điểm lịch sử – cụ thể, quan điểm toàn diện và phát triển."},{"c":1,"q":"Ý nghĩa của việc học tập môn Tư tưởng Hồ Chí Minh đối với sinh viên?","a":"Nâng cao năng lực tư duy lý luận và phương pháp công tác; bồi dưỡng phẩm chất đạo đức cách mạng; biết vận dụng vào học tập, rèn luyện và giải quyết vấn đề thực tiễn."},{"c":2,"q":"Bối cảnh lịch sử nào đã tác động đến sự hình thành tư tưởng Hồ Chí Minh?","a":"Trong nước: Việt Nam thành thuộc địa nửa phong kiến, khủng hoảng đường lối cứu nước. Thế giới: chủ nghĩa tư bản chuyển sang đế quốc, Cách mạng Tháng Mười Nga thắng lợi, Quốc tế Cộng sản ra đời."},{"c":2,"q":"Quê hương và gia đình đã ảnh hưởng như thế nào đến Hồ Chí Minh?","a":"Quê hương Nghệ An giàu truyền thống yêu nước, cần cù, hiếu học; gia đình nhà nho yêu nước (cụ Nguyễn Sinh Sắc) đã hun đúc lòng yêu nước và ý chí cứu nước của Người."},{"c":2,"q":"Giá trị truyền thống nào của dân tộc ảnh hưởng sâu sắc nhất đến Hồ Chí Minh?","a":"Chủ nghĩa yêu nước – giá trị cốt lõi, là dòng chủ lưu, là động lực thôi thúc Người ra đi tìm đường cứu nước."},{"c":2,"q":"Hồ Chí Minh đã tiếp thu những giá trị văn hoá phương Đông nào?","a":"Nho giáo (tu dưỡng đạo đức, nhân nghĩa); Phật giáo (từ bi, bác ái); Lão giáo (thoát vòng danh lợi, sống giản dị); văn hoá dân gian (nghệ thuật ứng xử cộng đồng)."},{"c":2,"q":"Hồ Chí Minh đã tiếp thu những giá trị văn hoá phương Tây nào?","a":"Tư tưởng dân chủ, tự do, bình đẳng, bác ái của các cuộc cách mạng tư sản Pháp – Mỹ; phương pháp tư duy khoa học và tinh thần thực tiễn."},{"c":2,"q":"Chủ nghĩa Mác – Lênin có vai trò như thế nào trong việc hình thành tư tưởng Hồ Chí Minh?","a":"Là cơ sở lý luận quyết định bước phát triển về chất: giúp Nguyễn Ái Quốc tìm ra con đường cứu nước đúng đắn – con đường cách mạng vô sản."},{"c":2,"q":"Sự kiện nào đánh dấu bước chuyển biến về chất trong tư tưởng của Nguyễn Ái Quốc?","a":"Tháng 7/1920 đọc Luận cương của Lênin về vấn đề dân tộc và thuộc địa, từ đó xác định con đường cứu nước là con đường cách mạng vô sản."},{"c":2,"q":"Giai đoạn 1921 – 1930 có ý nghĩa gì trong quá trình hình thành tư tưởng Hồ Chí Minh?","a":"Giai đoạn hình thành cơ bản: truyền bá chủ nghĩa Mác – Lênin vào Việt Nam (Đường Kách mệnh, 1927), thành lập Đảng (2/1930) với Cương lĩnh đúng đắn."},{"c":2,"q":"Giai đoạn 1930 – 1945 có ý nghĩa gì?","a":"Giai đoạn phát triển: lãnh đạo Cách mạng Tháng Tám thắng lợi, sáng lập Nhà nước dân chủ nhân dân đầu tiên ở Đông Nam Á."},{"c":2,"q":"Giai đoạn 1945 – 1969 có ý nghĩa gì?","a":"Giai đoạn hoàn thiện và phát triển: lãnh đạo hai cuộc kháng chiến, xây dựng chủ nghĩa xã hội ở miền Bắc, để lại Di chúc."},{"c":3,"q":"Nội dung cốt lõi của tư tưởng Hồ Chí Minh là gì?","a":"Độc lập dân tộc gắn liền với chủ nghĩa xã hội."},{"c":3,"q":"Vì sao Hồ Chí Minh khẳng định \"muốn cứu nước và giải phóng dân tộc không có con đường nào khác con đường cách mạng vô sản\"?","a":"Vì chỉ có cách mạng vô sản mới đánh đổ triệt để đế quốc, phong kiến, đem lại độc lập thật sự cho dân tộc và tự do, hạnh phúc cho nhân dân."},{"c":3,"q":"Lực lượng của cách mạng giải phóng dân tộc bao gồm những ai?","a":"Toàn dân tộc, với nòng cốt là khối liên minh công nhân – nông dân – trí thức."},{"c":3,"q":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc có quan hệ như thế nào với cách mạng vô sản ở chính quốc?","a":"Quan hệ khăng khít nhưng không phụ thuộc; cách mạng ở thuộc địa có thể nổ ra và thắng lợi trước."},{"c":3,"q":"Mục tiêu của chủ nghĩa xã hội theo tư tưởng Hồ Chí Minh là gì?","a":"Không ngừng nâng cao đời sống vật chất và tinh thần của nhân dân, trước hết là nhân dân lao động."},{"c":3,"q":"Động lực quan trọng và quyết định nhất của chủ nghĩa xã hội là gì?","a":"Con người – là nhân dân lao động, mà nòng cốt là công – nông – trí thức."},{"c":3,"q":"Theo Hồ Chí Minh, xây dựng chủ nghĩa xã hội phải chú ý những nội dung gì?","a":"Phát triển kinh tế (công – nông nghiệp là hai chân của nền kinh tế) gắn với phát triển văn hoá – xã hội; kết hợp hài hoà ba lợi ích; chống tham ô, lãng phí, quan liêu."},{"c":4,"q":"Bản chất của Đảng Cộng sản Việt Nam theo tư tưởng Hồ Chí Minh là gì?","a":"Đảng của giai cấp công nhân, đồng thời là Đảng của nhân dân lao động và của cả dân tộc Việt Nam."},{"c":4,"q":"Nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng là gì?","a":"Chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh."},{"c":4,"q":"Quy luật ra đời của Đảng Cộng sản Việt Nam theo tư tưởng Hồ Chí Minh là gì?","a":"Sự kết hợp chủ nghĩa Mác – Lênin với phong trào công nhân và phong trào yêu nước."},{"c":4,"q":"Vì sao Đảng phải thường xuyên tự đổi mới, tự chỉnh đốn?","a":"Vì Đảng là Đảng cầm quyền, dễ mắc bệnh quan liêu, xa dân; chỉ khi trong sạch, vững mạnh Đảng mới xứng đáng là người lãnh đạo, người đầy tớ thật trung thành của nhân dân."},{"c":4,"q":"Theo Hồ Chí Minh, Nhà nước ta là Nhà nước như thế nào?","a":"Nhà nước của dân, do dân, vì dân; tất cả quyền lực nhà nước thuộc về nhân dân."},{"c":4,"q":"Để xây dựng Nhà nước có hiệu lực pháp lý mạnh mẽ, Hồ Chí Minh chủ trương gì?","a":"Kết hợp nhuần nhuyễn quản lý bằng pháp luật với giáo dục đạo đức: tăng tính nghiêm minh của pháp luật đi đôi với đẩy mạnh giáo dục đạo đức."},{"c":5,"q":"Vai trò của đại đoàn kết dân tộc theo tư tưởng Hồ Chí Minh là gì?","a":"Vấn đề có ý nghĩa chiến lược, quyết định thành công của cách mạng: \"Đoàn kết, đoàn kết, đại đoàn kết. Thành công, thành công, đại thành công\"."},{"c":5,"q":"Lực lượng nòng cốt của khối đại đoàn kết dân tộc là gì?","a":"Khối liên minh công nhân – nông dân – trí thức dưới sự lãnh đạo của Đảng."},{"c":5,"q":"Hình thức tổ chức của khối đại đoàn kết dân tộc là gì?","a":"Mặt trận dân tộc thống nhất – nơi đại đoàn kết biến thành sức mạnh vật chất, lực lượng vật chất có tổ chức."},{"c":5,"q":"Nguyên tắc xây dựng khối đại đoàn kết dân tộc là gì?","a":"Đoàn kết trên nền tảng liên minh công – nông – trí thức, đặt dưới sự lãnh đạo của Đảng; lấy lợi ích tối cao của dân tộc làm điểm tương đồng; kết hợp đoàn kết với đấu tranh."},{"c":5,"q":"Ba ngọn cờ đoàn kết quốc tế của Hồ Chí Minh là gì?","a":"Với phong trào cộng sản và công nhân quốc tế: độc lập dân tộc gắn liền với chủ nghĩa xã hội; với các dân tộc: độc lập, tự do, bình đẳng; với lực lượng tiến bộ: hoà bình trong công lý."},{"c":5,"q":"Khẩu hiệu đoàn kết quốc tế do Hồ Chí Minh nêu lên là gì?","a":"\"Vô sản tất cả các nước và các dân tộc bị áp bức trên thế giới đoàn kết lại!\""},{"c":6,"q":"Quan điểm của Hồ Chí Minh về vai trò của đạo đức là gì?","a":"Đạo đức là gốc của người cách mạng: \"cũng như sông thì có nguồn mới có nước, không có nguồn thì sông cạn\"."},{"c":6,"q":"Chuẩn mực đạo đức cách mạng cơ bản nhất theo Hồ Chí Minh là gì?","a":"Trung với nước, hiếu với dân – điều chủ chốt nhất của đạo đức cách mạng."},{"c":6,"q":"\"Cần, kiệm, liêm, chính\" được Hồ Chí Minh giải thích như thế nào?","a":"Cần: siêng năng; Kiệm: tiết kiệm; Liêm: trong sạch, không tham lam; Chính: thẳng thắn, đứng đắn. \"Cần, kiệm, liêm là gốc rễ của chính\"."},{"c":6,"q":"Kẻ thù của đạo đức cách mạng là gì?","a":"Chủ nghĩa cá nhân – \"kẻ thù hung ác\", đẻ ra tham ô, lãng phí, quan liêu, bè phái."},{"c":6,"q":"Theo Hồ Chí Minh, thế nào là \"người tốt, việc tốt\"?","a":"Nói đi đôi với làm, nêu gương đạo đức trong công việc và lối sống; \"lấy gương người tốt, việc tốt để hằng ngày giáo dục lẫn nhau\"."},{"c":6,"q":"Quan điểm của Hồ Chí Minh về xây dựng con người mới xã hội chủ nghĩa?","a":"Con người mới xã hội chủ nghĩa phải có tư tưởng, đạo đức và tác phong xã hội chủ nghĩa; \"muốn xây dựng chủ nghĩa xã hội, trước hết cần có những con người xã hội chủ nghĩa\"."},{"c":6,"q":"Sinh viên cần làm gì để học tập và làm theo tư tưởng, đạo đức Hồ Chí Minh?","a":"Học tập tốt, rèn luyện đạo đức (cần kiệm liêm chính, chí công vô tư), chống chủ nghĩa cá nhân, sống có lý tưởng, gắn học tập với thực tiễn và hoạt động vì cộng đồng."}],"ESSAYS":[{"t":"1. Chức năng của văn hoá theo tư tưởng Hồ Chí Minh. Liên hệ trách nhiệm sinh viên.","h":"<h4>Mở bài</h4>\n<ul><li>Văn hoá là một bộ phận trong tư tưởng Hồ Chí Minh; Người coi <span class=\"kw\">văn hoá vừa là mục tiêu, vừa là động lực</span> của sự nghiệp cách mạng và xây dựng đất nước.</li></ul>\n<h4>Thân bài – các chức năng của văn hoá</h4>\n<ul>\n<li><b>Bồi dưỡng tư tưởng, đạo đức, nhân cách con người</b> (\"trồng người\"): văn hoá soi đường cho quốc dân đi, hướng con người tới chân – thiện – mỹ.</li>\n<li><b>Nâng cao dân trí, phát triển nguồn nhân lực</b>: \"một dân tộc dốt là một dân tộc yếu\"; chống giặc dốt song song với chống giặc đói, giặc ngoại xâm.</li>\n<li><b>Gìn giữ và phát huy bản sắc dân tộc</b>: văn hoá đậm đà bản sắc dân tộc là nền tảng tinh thần, là \"sức mạnh mềm\" trong hội nhập.</li>\n<li><b>Tạo động lực tinh thần cho phát triển kinh tế – xã hội</b>: văn hoá thấm sâu vào mọi lĩnh vực, thúc đẩy lao động sáng tạo.</li>\n</ul>\n<h4>Liên hệ sinh viên</h4>\n<ul><li>Không ngừng <b>học tập nâng cao dân trí</b>, rèn luyện đạo đức, lối sống lành mạnh; giữ gìn tiếng Việt và các giá trị văn hoá dân tộc; tiếp thu có chọn lọc tinh hoa văn hoá nhân loại, không sính ngoại lai căng; tích cực tham gia các hoạt động văn hoá, tình nguyện vì cộng đồng.</li></ul>\n<h4>Kết bài</h4>\n<ul><li>Thấm nhuần tư tưởng văn hoá Hồ Chí Minh giúp sinh viên phát triển toàn diện, trở thành \"con người mới\" vừa hồng vừa chuyên.</li></ul>"},{"t":"2. Chuẩn mực đạo đức cách mạng theo tư tưởng Hồ Chí Minh. Học tập theo Người và liên hệ bản thân.","h":"<h4>Mở bài</h4>\n<ul><li>Đạo đức là \"gốc\" của người cách mạng; Hồ Chí Minh là tấm gương đạo đức trong sáng, là chuẩn mực để mỗi người học tập, noi theo.</li></ul>\n<h4>Thân bài – các chuẩn mực đạo đức cách mạng</h4>\n<ul>\n<li><span class=\"kw\">Trung với nước, hiếu với dân</span> – điều chủ chốt nhất: suốt đời phấn đấu vì độc lập dân tộc và chủ nghĩa xã hội, đặt lợi ích của Tổ quốc, của nhân dân lên trên hết.</li>\n<li><span class=\"kw\">Yêu thương con người</span>, sống có tình có nghĩa: khoan dung, độ lượng, hết lòng vì con người.</li>\n<li><span class=\"kw\">Cần, kiệm, liêm, chính, chí công vô tư</span>: siêng năng, tiết kiệm, trong sạch, thẳng thắn; việc công đặt trên việc tư.</li>\n<li><span class=\"kw\">Tinh thần quốc tế trong sáng</span>: đoàn kết với nhân dân lao động và các dân tộc bị áp bức trên thế giới.</li>\n<li>Kiên quyết <span class=\"kw\">chống chủ nghĩa cá nhân</span> – \"kẻ thù hung ác\" của đạo đức cách mạng.</li>\n</ul>\n<h4>Học tập và làm theo Hồ Chí Minh</h4>\n<ul><li>Học tập bằng <b>nêu gương</b>: \"nói đi đôi với làm\"; tu dưỡng đạo đức <b>suốt đời</b>; \"xây đi đôi với chống\" – xây cái tốt, chống cái xấu, nhất là chống chủ nghĩa cá nhân, tham ô, lãng phí, quan liêu.</li></ul>\n<h4>Liên hệ sinh viên</h4>\n<ul><li>Rèn luyện <b>cần, kiệm, liêm, chính</b> trong học tập và sinh hoạt (siêng năng học tập, tiết kiệm, trung thực trong thi cử); sống có lý tưởng, có trách nhiệm với gia đình, nhà trường và xã hội; tích cực đấu tranh với biểu hiện tiêu cực trong môi trường học đường.</li></ul>\n<h4>Kết bài</h4>\n<ul><li>Chuẩn mực đạo đức Hồ Chí Minh là hành trang tinh thần để sinh viên trở thành công dân tốt, góp phần xây dựng xã hội văn minh.</li></ul>"},{"t":"3. Những giá trị truyền thống của dân tộc ảnh hưởng đến sự hình thành tư tưởng Hồ Chí Minh. Liên hệ sinh viên.","h":"<h4>Mở bài</h4>\n<ul><li>Tư tưởng Hồ Chí Minh bắt nguồn sâu xa từ <span class=\"kw\">giá trị truyền thống tốt đẹp của dân tộc Việt Nam</span> – mảnh đất nuôi dưỡng tâm hồn và nhân cách của Người.</li></ul>\n<h4>Thân bài – các giá trị truyền thống chủ yếu</h4>\n<ul>\n<li><span class=\"kw\">Chủ nghĩa yêu nước</span> – giá trị cốt lõi, dòng chủ lưu: Hồ Chí Minh nâng chủ nghĩa yêu nước truyền thống lên thành <b>chủ nghĩa yêu nước xã hội chủ nghĩa</b>, gắn yêu nước với yêu chủ nghĩa xã hội.</li>\n<li><span class=\"kw\">Tinh thần đoàn kết, tương thân tương ái</span>: \"lá lành đùm lá rách\" – cơ sở của tư tưởng đại đoàn kết dân tộc.</li>\n<li><span class=\"kw\">Cần cù, sáng tạo, hiếu học</span>: ý chí tự lực tự cường, tinh thần \"không có việc gì khó\".</li>\n<li><span class=\"kw\">Lạc quan, yêu đời, tin vào chính nghĩa</span>: niềm tin tất thắng của cách mạng.</li>\n<li><span class=\"kw\">Trọng nhân nghĩa, đạo lý</span>: \"thương người như thể thương thân\" – nền của lòng nhân ái Hồ Chí Minh.</li>\n</ul>\n<h4>Liên hệ sinh viên</h4>\n<ul><li>Giữ gìn và phát huy truyền thống: <b>yêu nước</b> bằng hành động thiết thực (học tốt, sẵn sàng cống hiến); <b>đoàn kết, giúp đỡ</b> bạn bè; <b>hiếu học, tự lực</b> vươn lên; sống có <b>đạo lý, nhân nghĩa</b>; đồng thời phê phán, loại bỏ những hủ tục, tư tưởng lạc hậu.</li></ul>\n<h4>Kết bài</h4>\n<ul><li>Truyền thống dân tộc là \"nguồn\" nuôi dưỡng tư tưởng Hồ Chí Minh; sinh viên hôm nay phải là người kế thừa xứng đáng và làm giàu thêm truyền thống ấy.</li></ul>"},{"t":"4. Cơ sở lý luận hình thành tư tưởng Hồ Chí Minh. Vận dụng các giá trị cốt lõi của cơ sở lý luận đó hiện nay.","h":"<h4>Mở bài</h4>\n<ul><li>Tư tưởng Hồ Chí Minh hình thành trên cơ sở lý luận phong phú, là sự kết hợp nhuần nhuyễn giữa <span class=\"kw\">dân tộc và thời đại, Đông và Tây</span>.</li></ul>\n<h4>Thân bài – ba cơ sở lý luận</h4>\n<ul>\n<li><b>Giá trị truyền thống tốt đẹp của dân tộc Việt Nam</b>: chủ nghĩa yêu nước, tinh thần đoàn kết, cần cù sáng tạo, nhân nghĩa – là tiền đề, là \"mảnh đất\" đầu tiên.</li>\n<li><b>Tinh hoa văn hoá nhân loại</b>: văn hoá phương Đông (Nho – Phật – Lão, văn hoá dân gian) và văn hoá phương Tây (tư tưởng dân chủ, tự do, bình đẳng; tư duy khoa học) – được Người tiếp thu <b>có chọn lọc, có phê phán</b>.</li>\n<li><b>Chủ nghĩa Mác – Lênin</b> – cơ sở lý luận <span class=\"kw\">quyết định bước phát triển về chất</span>: thế giới quan, phương pháp luận khoa học; giúp Người tìm ra con đường cứu nước đúng đắn.</li>\n</ul>\n<h4>Vận dụng hiện nay</h4>\n<ul>\n<li><b>Kiên định</b> chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, đồng thời <b>vận dụng sáng tạo</b>, chống giáo điều, rập khuôn.</li>\n<li>Kế thừa, phát huy truyền thống dân tộc; chủ động hội nhập, tiếp thu tinh hoa văn hoá nhân loại, làm giàu bản sắc văn hoá Việt Nam.</li>\n<li>Đấu tranh chống các quan điểm sai trái, thù địch phủ nhận nền tảng tư tưởng của Đảng.</li>\n</ul>\n<h4>Kết bài</h4>\n<ul><li>Nắm vững cơ sở lý luận giúp ta hiểu sâu sắc tính khoa học, cách mạng của tư tưởng Hồ Chí Minh và vận dụng đúng đắn trong giai đoạn mới.</li></ul>"},{"t":"5. Vai trò và phương thức xây dựng khối đại đoàn kết dân tộc theo tư tưởng Hồ Chí Minh. Trách nhiệm của sinh viên.","h":"<h4>Mở bài</h4>\n<ul><li>Đại đoàn kết dân tộc là tư tưởng lớn, xuyên suốt của Hồ Chí Minh: <span class=\"kw\">\"Đoàn kết, đoàn kết, đại đoàn kết. Thành công, thành công, đại thành công.\"</span></li></ul>\n<h4>Thân bài – vai trò</h4>\n<ul>\n<li>Đại đoàn kết dân tộc là vấn đề có <span class=\"kw\">ý nghĩa chiến lược</span>, <b>quyết định thành công</b> của cách mạng; là mục tiêu, nhiệm vụ hàng đầu.</li>\n<li>Là nguồn sức mạnh tổng hợp, tạo nên lực lượng vật chất và tinh thần to lớn để chiến thắng mọi kẻ thù, xây dựng đất nước.</li>\n</ul>\n<h4>Thân bài – phương thức xây dựng</h4>\n<ul>\n<li>Tổ chức thành <span class=\"kw\">lực lượng vật chất có tổ chức</span>: hình thức là <b>Mặt trận dân tộc thống nhất</b> – đại đoàn kết không dừng ở khẩu hiệu mà phải thành sức mạnh vật chất.</li>\n<li>Nền tảng là <span class=\"kw\">khối liên minh công – nông – trí thức</span> đặt dưới sự lãnh đạo của Đảng.</li>\n<li>Lấy <span class=\"kw\">lợi ích tối cao của dân tộc</span> làm điểm tương đồng; \"cầu đồng tồn dị\", xóa bỏ thành kiến, đoàn kết thật sự, chân thành.</li>\n<li><span class=\"kw\">Kết hợp đoàn kết với đấu tranh</span>: đấu tranh để củng cố, mở rộng khối đoàn kết.</li>\n</ul>\n<h4>Trách nhiệm của sinh viên</h4>\n<ul><li>Đoàn kết, giúp đỡ bạn bè; tôn trọng sự đa dạng (dân tộc, tôn giáo, vùng miền); tích cực tham gia hoạt động tập thể, tình nguyện; kiên quyết đấu tranh với biểu hiện chia rẽ, kỳ thị, bè phái trong học đường và xã hội.</li></ul>\n<h4>Kết bài</h4>\n<ul><li>Sinh viên là lực lượng trẻ, phải là hạt nhân đoàn kết trong nhà trường, góp phần xây dựng khối đại đoàn kết toàn dân tộc vững chắc.</li></ul>"}],"CHAP_NAMES":{"1":"Chương 1 – Khái niệm, đối tượng, phương pháp","2":"Chương 2 – Cơ sở, quá trình hình thành","3":"Chương 3 – Độc lập dân tộc gắn liền CNXH","4":"Chương 4 – Đảng và Nhà nước","5":"Chương 5 – Đại đoàn kết","6":"Chương 6 – Văn hoá, đạo đức, con người"},"LETTERS":["A","B","C","D"],"NAV_TITLES":{"quiz":"Mục lục trắc nghiệm","flash":"Mục lục câu hỏi ngắn","essay":"Mục lục tự luận","timeline":"Mục lục timeline","keys":"Mục lục ý chính"},"KEYS_HTML":"\n  <div class=\"card\">\n    <h3 id=\"keysec-0\" style=\"color:var(--accent);margin-top:0\">Dòng thời gian cần nhớ</h3>\n    <div class=\"tl\">\n      <div class=\"tl-item\"><span class=\"tl-year\">1890</span> – Nguyễn Sinh Cung (Hồ Chí Minh) sinh tại Nghệ An.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1911</span> – Ra đi tìm đường cứu nước từ bến Nhà Rồng.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1919</span> – Gửi <i>Bản yêu sách của nhân dân An Nam</i> tới Hội nghị Versailles.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">7/1920</span> – Đọc <i>Luận cương của Lênin về vấn đề dân tộc và thuộc địa</i> → tìm ra con đường cứu nước.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">12/1920</span> – Đại hội Tours: bỏ phiếu tán thành Quốc tế III, trở thành người cộng sản.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1923–1924</span> – Học tập, hoạt động tại Liên Xô.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1927</span> – Xuất bản <i>Đường Kách mệnh</i> (tập bài giảng ở Quảng Châu).</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">2/1930</span> – Chủ trì hợp nhất 3 tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam; soạn <i>Cương lĩnh</i> đầu tiên.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1941</span> – Về nước, chủ trì Hội nghị TW 8, thành lập Mặt trận Việt Minh.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">8/1945</span> – Lãnh đạo Tổng khởi nghĩa; <i>Hiệu triệu tổng khởi nghĩa</i> (\"Hỡi đồng bào yêu quý!...\").</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">2/9/1945</span> – Đọc <i>Tuyên ngôn Độc lập</i>, khai sinh nước Việt Nam Dân chủ Cộng hòa.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">19/12/1946</span> – <i>Lời kêu gọi toàn quốc kháng chiến</i>.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1951</span> – Đại hội II: Đảng đổi tên thành Đảng Lao động Việt Nam.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1957</span> – \"Nước Việt Nam là một, dân tộc Việt Nam là một...\"</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1958</span> – Viết bài <i>Đạo đức cách mạng</i>.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1969</span> – <i>Di chúc</i>; bài <i>Nâng cao đạo đức cách mạng, quét sạch chủ nghĩa cá nhân</i>; qua đời 2/9/1969.</div>\n      <div class=\"tl-item\"><span class=\"tl-year\">1991</span> – Đại hội VII: chính thức dùng thuật ngữ \"Tư tưởng Hồ Chí Minh\"; Cương lĩnh 1991.</div>\n    </div>\n  </div>\n  <div class=\"card\">\n    <h3 id=\"keysec-1\" style=\"color:var(--accent);margin-top:0\">Công thức nhớ nhanh</h3>\n    <div class=\"formula\"><b>3 nguồn gốc TTHCM:</b> truyền thống dân tộc + tinh hoa văn hoá nhân loại + chủ nghĩa Mác–Lênin (quyết định bước phát triển về chất).</div>\n    <div class=\"formula\"><b>Nội dung cốt lõi:</b> độc lập dân tộc <i>gắn liền với</i> chủ nghĩa xã hội. Độc lập dân tộc là <b>điều kiện tiên quyết</b>, CNXH là mục tiêu.</div>\n    <div class=\"formula\"><b>3 ngọn cờ đoàn kết quốc tế:</b> phong trào cộng sản &amp; công nhân → <b>độc lập dân tộc gắn liền CNXH</b> · các dân tộc → <b>độc lập, tự do, bình đẳng</b> · lực lượng tiến bộ → <b>hoà bình trong công lý</b>.</div>\n    <div class=\"formula\"><b>3 chuẩn mực đạo đức:</b> (1) trung với nước, hiếu với dân · (2) yêu thương con người · (3) cần, kiệm, liêm, chính, chí công vô tư.</div>\n    <div class=\"formula\"><b>4 đức:</b> cần – kiệm – liêm – chính (\"cần, kiệm, liêm là gốc rễ của chính\"). <b>Kẻ thù:</b> chủ nghĩa cá nhân.</div>\n    <div class=\"formula\"><b>3 đặc trưng CNXH:</b> kinh tế → <b>sở hữu xã hội về tư liệu sản xuất</b> · chính trị → <b>dân chủ triệt để</b> · văn hoá → <b>tiên tiến, đậm đà bản sắc dân tộc</b>.</div>\n    <div class=\"formula\"><b>Đảng:</b> bản chất giai cấp công nhân · nền tảng tư tưởng: CNMLN + TTHCM · quy luật ra đời: CNMLN + phong trào công nhân + phong trào yêu nước.</div>\n    <div class=\"formula\"><b>Nhà nước:</b> của dân, do dân, vì dân · pháp trị đi đôi với đức trị.</div>\n  </div>\n  <div class=\"card\">\n    <h3 id=\"keysec-2\" style=\"color:var(--accent);margin-top:0\">Cụm từ khóa hay bị bẫy</h3>\n    <ul>\n      <li><span class=\"kw\">1991 – Đại hội VII</span>: năm Đảng chính thức dùng thuật ngữ \"Tư tưởng Hồ Chí Minh\".</li>\n      <li><span class=\"kw\">Hiệu triệu tổng khởi nghĩa (8/1945)</span> ≠ <span class=\"kw\">Lời kêu gọi toàn quốc kháng chiến (19/12/1946)</span>: cùng mở đầu \"Hỡi đồng bào...\" nhưng khác thời điểm.</li>\n      <li><span class=\"kw\">Mâu thuẫn tồn tại</span> (3 cặp) ≠ <span class=\"kw\">mâu thuẫn cơ bản</span> (nông dân–địa chủ; dân tộc–thực dân Pháp).</li>\n      <li><span class=\"kw\">Điều kiện tiên quyết</span> (độc lập dân tộc) ≠ <span class=\"kw\">nội dung cốt lõi</span> (độc lập dân tộc gắn liền CNXH).</li>\n      <li><span class=\"kw\">Đường Kách mệnh (1927)</span>: \"Tư cách một người cách mệnh\"; \"giàu sang không thể quyến rũ...\".</li>\n      <li><span class=\"kw\">7/1960, Đại hội sản xuất Hà Đông</span>: \"Đảng ta là một đảng cách mạng, ngoài lợi ích của công nhân và nông dân, Đảng ta không có lợi ích nào khác\".</li>\n    </ul>\n  </div>\n  <footer class=\"note\">Đáp án được đối chiếu với giáo trình Tư tưởng Hồ Chí Minh và các ngân hàng câu hỏi có đáp án công khai. Hai câu cần lưu ý: <b>Chương 2 – Câu 1</b> (đề hỏi \"tồn tại\" nên chọn \"tất cả\"; nếu đề hỏi \"cơ bản\" thì chỉ có 2 cặp) và <b>Chương 5 – Câu 12</b> (nên đối chiếu thêm đáp án của giảng viên).</footer>\n"};
